import { EventDispatcher } from '../core/index.js';
import { SEKAI64_MODULE_VERSION } from '../modules/index.js';
export class RendererRecoveryModule extends EventDispatcher {
    options;
    id = 'sekai64.recovery';
    version = SEKAI64_MODULE_VERSION;
    resources = new Map();
    context;
    recovering;
    constructor(options = {}) {
        super();
        this.options = options;
    }
    setup(context) { this.context = context; return { capabilities: { automaticDeviceRecreation: typeof context.renderer.recover === 'function', resourceRestoration: true, terminalFailure: true }, recover: recovery => this.recover(recovery.reason), dispose: () => this.dispose() }; }
    register(resource) { if (this.resources.has(resource.id))
        throw new Error(`Recovery resource is already registered: ${resource.id}`); this.resources.set(resource.id, resource); return () => { if (this.resources.get(resource.id) === resource)
        this.resources.delete(resource.id); }; }
    recover(reason) { if (this.recovering)
        return this.recovering; this.recovering = this.runRecovery(reason).finally(() => { this.recovering = undefined; }); return this.recovering; }
    async runRecovery(reason) {
        const renderer = this.context?.renderer;
        if (!renderer?.recover)
            throw new Error('The active renderer does not expose automatic recovery. Use Player world replacement as the fallback.');
        const maximum = Math.max(1, Math.floor(this.options.maxAttempts ?? 2));
        let lastError;
        for (let attempt = 1; attempt <= maximum; attempt += 1) {
            try {
                this.emit('progress', { attempt, progress: 0, message: 'Recreating renderer backend' });
                await renderer.recover({ reason, onProgress: (progress, message) => this.emit('progress', { attempt, progress, ...(message ? { message } : {}) }) });
                let index = 0;
                for (const resource of this.resources.values()) {
                    await resource.restore();
                    index += 1;
                    this.emit('progress', { attempt, progress: this.resources.size === 0 ? 1 : index / this.resources.size, message: `Restored ${resource.id}` });
                }
                this.emit('recovered', { attempt });
                return;
            }
            catch (error) {
                lastError = error;
                this.emit('failed', { attempt, error });
            }
        }
        throw new Error(`Sekai64 renderer recovery failed after ${maximum} attempts: ${lastError instanceof Error ? lastError.message : String(lastError)}`);
    }
    dispose() { this.resources.clear(); this.context = undefined; this.clearListeners(); }
}
export function createRendererRecoveryModule(options = {}) { return new RendererRecoveryModule(options); }